function hashWordDeterministic(input: string): number {
  let h = 2166136261;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function toPlateSlug(scientificName: string): string {
  return scientificName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function tupleToPlate(tuple: CompactPlateTuple): BotanicalPlate {
  return {
    scientificName: tuple[0],
    commonName: tuple[1],
    sourceAtlas: ATLAS_LABELS[tuple[2]],
    miniThumbUrl: `/plates/${toPlateSlug(tuple[0])}.webp`,
    thumbUrl: tuple[3],
    fullUrl: tuple[4],
  };
}

export function getBotanicalPlate(word: string): BotanicalPlate | null {
  const normalized = (word || "").trim().toLowerCase();
  if (!normalized) return null;
  const direct = COMPACT_PLATES[normalized];
  if (direct) return tupleToPlate(direct);
  if (RESERVE_PLATES.length === 0) return null;
  const idx = hashWordDeterministic(normalized) % RESERVE_PLATES.length;
  return tupleToPlate(RESERVE_PLATES[idx]);
}
